import json, pandas as pd, numpy as np
facts = json.load(open('facts.json'))
for f in facts:
    env = {'pd': pd, 'np': np}
    for name, path in f['tables'].items():
        env[name] = pd.read_csv(path)
    try:
        val = eval(f['code'], env)
        print('===', f['id'])
        print(val)
    except Exception as e:
        print('ERROR', f['id'], type(e).__name__, e)
EOF

